#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
void tick(const unsigned char *in, size_t rows, size_t cols, unsigned char *out) {
    for (size_t r = 0; r < rows; r++)
        for (size_t c = 0; c < cols; c++) {
            int n = 0;
            for (int dr = -1; dr <= 1; dr++)
                for (int dc = -1; dc <= 1; dc++) {
                    long rr = (long)r + dr, cc = (long)c + dc;
                    if ((dr || dc) && rr >= 0 && cc >= 0 && (size_t)rr < rows &&
                        (size_t)cc < cols)
                        n += !!in[rr * cols + cc];
                }
            out[r * cols + c] = (n == 3 || (n == 2 && in[r * cols + c]));
        }
}

